"use client";

import {
  useEffect,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from "react";
import Link from "next/link";
import { Clock3, LockKeyhole, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
  DialogClose,
} from "@/components/ui/dialog";
import { PRICE_CONFIG } from "@/lib/pricing";
import {
  PlanCard,
  upgradeContexts,
  type UpgradeFeature,
} from "./pricing/plan-card";
export { upgradeContexts, type UpgradeFeature } from "./pricing/plan-card";

export type PremiumPrice = { symbol: string; amount: number };
export function PremiumUpgradeDialog({
  premiumPrice = PRICE_CONFIG.DEFAULT,
  formRef,
  returnFocusRef,
  reason = "allowance",
  allowanceScope = "daily",
  feature,
  onUpgrade,
  onClose,
  children,
}: {
  premiumPrice?: PremiumPrice;
  formRef?: RefObject<HTMLFormElement | null>;
  returnFocusRef?: RefObject<HTMLElement | null>;
  reason?: "recipient-limit" | "allowance" | "feature";
  allowanceScope?: "daily" | "monthly" | "both";
  feature?: UpgradeFeature;
  onUpgrade?: () => void;
  children?: ReactNode;
  onClose: () => void;
}) {
  const [checkoutPending, setCheckoutPending] = useState(false);
  const [checkoutError, setCheckoutError] = useState("");
  const attemptKey = useRef<string | null>(null);
  const checkoutRequest = useRef<AbortController | null>(null);
  async function startCheckout() {
    if (checkoutRequest.current) return;
    const controller = new AbortController();
    checkoutRequest.current = controller;
    setCheckoutPending(true);
    setCheckoutError("");
    attemptKey.current ??= crypto.randomUUID();
    try {
      const response = await fetch("/api/billing/checkout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          plan: "paid_monthly",
          idempotencyKey: attemptKey.current,
        }),
        signal: controller.signal,
      });
      const result = await response.json();
      if (!response.ok) {
        if (result.code === "CHECKOUT_ATTEMPT_FINISHED")
          attemptKey.current = null;
        throw new Error(
          result.error || "Could not open checkout. Please try again.",
        );
      }
      if (typeof result.checkoutUrl !== "string" || !result.checkoutUrl)
        throw new Error("Could not open checkout. Please try again.");
      window.location.assign(result.checkoutUrl);
    } catch (error) {
      if (controller.signal.aborted) return;
      setCheckoutError(
        error instanceof Error
          ? error.message
          : "Could not open checkout. Please try again.",
      );
      setCheckoutPending(false);
      checkoutRequest.current = null;
    }
  }

  const trigger = useRef<HTMLElement | null>(null);
  useEffect(
    () => () => {
      checkoutRequest.current?.abort();
    },
    [],
  );
  const price = `${premiumPrice.symbol}${premiumPrice.amount}`;
  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent
        data-upgrade-reason={reason}
        className="upgrade-modal flex w-[calc(100%-32px)] max-w-205 flex-col overflow-hidden rounded-[22px] border border-upgrade-border bg-upgrade-app p-0 text-upgrade-text shadow-upgrade-modal"
        onOpenAutoFocus={() => {
          trigger.current =
            returnFocusRef?.current ??
            formRef?.current?.querySelector<HTMLButtonElement>(
              "button[type='submit']",
            ) ??
            (document.activeElement instanceof HTMLElement
              ? document.activeElement
              : null);
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
          if (trigger.current?.isConnected) trigger.current.focus();
        }}
      >
        <header className="flex shrink-0 items-start justify-between gap-3 px-4 pb-2.5 pt-5.5 min-[700px]:px-6">
          <div className="min-w-0">
            <DialogTitle className="text-[22px] font-bold tracking-[-0.02em]">
              Upgrade to Premium
            </DialogTitle>
            <DialogDescription className="mt-1 text-sm leading-relaxed text-upgrade-muted">
              Send 20× more and follow up without leaving Mailloop.
            </DialogDescription>
          </div>
          <DialogClose asChild>
            <Button
              variant="outline"
              size="icon"
              aria-label="Close upgrade dialog"
              className="shrink-0 rounded-[10px] border-upgrade-border bg-upgrade-surface text-upgrade-muted hover:bg-upgrade-surface2"
            >
              <X aria-hidden="true" />
            </Button>
          </DialogClose>
        </header>
        {reason === "allowance" || reason === "recipient-limit" || feature ? (
          <div
            aria-live="polite"
            className="mx-4 mt-1.5 flex shrink-0 items-center gap-2 self-start rounded-full border border-upgrade-border bg-upgrade-okbg px-3 py-1.75 text-[13px] min-[700px]:mx-6"
          >
            {reason === "allowance" ? (
              <Clock3 aria-hidden="true" className="size-4 shrink-0" />
            ) : feature ? (
              <LockKeyhole aria-hidden="true" className="size-4 shrink-0" />
            ) : null}
            <span>
              {reason === "recipient-limit"
                ? "More recipients per campaign with Premium"
                : reason === "allowance"
                  ? allowanceScope === "both"
                    ? "Sending limits reached"
                    : `${allowanceScope === "monthly" ? "Monthly" : "Daily"} sending limit reached`
                  : feature
                    ? upgradeContexts[feature]
                    : null}
            </span>
          </div>
        ) : null}
        <div
          data-plan-cards
          data-upgrade-body
          role="region"
          aria-label="Plan comparison"
          tabIndex={0}
          className="grid min-h-0 flex-1 auto-rows-max grid-cols-1 content-start focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-ring gap-4 overflow-auto overscroll-contain px-4 pb-2 pt-4 min-[700px]:grid-cols-[minmax(0,1fr)_minmax(0,1.15fr)] min-[700px]:px-6"
        >
          {children && (
            <div className="min-w-0 text-sm min-[700px]:col-span-2">
              {children}
            </div>
          )}
          <PlanCard price={premiumPrice} current />
          <PlanCard premium price={premiumPrice} feature={feature} />
        </div>
        <footer className="flex shrink-0 flex-col gap-2.5 border-t border-dotted border-separator bg-upgrade-app px-4 pb-4.5 pt-3.5 min-[700px]:px-6">
          <div className="flex flex-wrap items-center gap-2.5">
            <Button
              type="button"
              className="upgrade-cta upgrade-shine relative isolate h-auto min-h-12 flex-1 overflow-hidden whitespace-normal rounded-[13px] bg-upgrade-gradient px-4 py-3.5 text-[15px] font-bold text-upgrade-btn-fg"
              onClick={() => (onUpgrade ? onUpgrade() : void startCheckout())}
              disabled={checkoutPending}
              aria-busy={checkoutPending}
            >
              <span className="relative z-10">
                {checkoutPending
                  ? "Opening checkout…"
                  : `Upgrade for ${price} / month`}
              </span>
            </Button>
            <DialogClose asChild>
              <Button
                type="button"
                variant="outline"
                className="h-auto min-h-12 rounded-[13px] border-upgrade-border bg-transparent px-4 py-3 text-upgrade-muted hover:bg-upgrade-surface2"
              >
                Maybe later
              </Button>
            </DialogClose>
          </div>
          {checkoutError && (
            <p role="alert" className="text-xs leading-snug">
              {checkoutError}
            </p>
          )}
          <p className="text-xs leading-[1.45] text-upgrade-muted">
            Billed monthly. Final quote shown at checkout. Repeat sends count
            toward your allowances. Review the final amount in checkout.{" "}
            <Link
              href="/pricing"
              className="text-upgrade-text underline underline-offset-3 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
            >
              View full pricing
            </Link>
          </p>
        </footer>
      </DialogContent>
    </Dialog>
  );
}
